    const r = await fetch("/api/fetch", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        plugin: "readeck",
        url: ctx.config.server + "/api/bookmarks/" + id + "/" + resource,
        dest,
        headers: { Authorization: "Bearer " + ctx.token, ...headers },
      }),
    });
